	handle->ifaceSystem.deactive_actuator_raised = bool_false;
	handle->timeEvents.smartGarageDoorSystem_SmartGarageDoorSystem_IoT_Template_DeviceSwitchStatus_on_tev0_raised = bool_false;
	handle->timeEvents.smartGarageDoorSystem_SmartGarageDoorSystem_IoT_Template_ControllerComponent_Controller_Component_isON__Controller_Receiving_and_Sending_Updates__Standby_tev0_raised = bool_false;
