static void smartgaragedoorsystem_eventqueue_init(smartgaragedoorsystem_eventqueue * eq, smartgaragedoorsystem_event *buffer, sc_integer capacity)
{
	eq->events = buffer;
	eq->capacity = capacity;
	eq->push_index = 0;
	eq->pop_index = 0;
	eq->size = 0;
}

static sc_integer smartgaragedoorsystem_eventqueue_size(smartgaragedoorsystem_eventqueue * eq)
{
	return eq->size;
}

static smartgaragedoorsystem_event smartgaragedoorsystem_eventqueue_pop(smartgaragedoorsystem_eventqueue * eq)
{
	smartgaragedoorsystem_event event;
	if(smartgaragedoorsystem_eventqueue_size(eq) <= 0) {
		smartgaragedoorsystem_event_init(&event, SmartGarageDoorSystem_invalid_event);
	}
	else {
		event = eq->events[eq->pop_index];
		
		if(eq->pop_index < eq->capacity - 1) {
			eq->pop_index++;
		} 
		else {
			eq->pop_index = 0;
		}
		eq->size--;
	}
	return event;
}
static sc_boolean smartgaragedoorsystem_eventqueue_push(smartgaragedoorsystem_eventqueue * eq, smartgaragedoorsystem_event ev)
{
	if(smartgaragedoorsystem_eventqueue_size(eq) == eq->capacity) {
		return bool_false;
	}
	else {
		eq->events[eq->push_index] = ev;
		
		if(eq->push_index < eq->capacity - 1) {
			eq->push_index++;
		}
		else {
			eq->push_index = 0;
		}
		eq->size++;
		
		return bool_true;
	}
}
static void smartgaragedoorsystem_event_init(smartgaragedoorsystem_event * ev, SmartGarageDoorSystemEventID name)
{
	ev->name = name;
}

static void smartGarageDoorSystem_add_event_to_queue(smartgaragedoorsystem_eventqueue * eq, SmartGarageDoorSystemEventID name)
{
	smartgaragedoorsystem_event event;
	smartgaragedoorsystem_event_init(&event, name);
	smartgaragedoorsystem_eventqueue_push(eq, event);
}

